        window.clear(); glEnable(GL_DEPTH_TEST); program.use()
        program["angle"]=angle; program["aspect"]=window.width/max(1,window.height)
        mesh.draw(GL_TRIANGLES); program.stop()
    @window.event
    def on_close():
